class Solution:
    def diameterOfBinaryTree(self, root):
        best = 0
        def height(node):          # number of nodes on the longest downward path
            nonlocal best
            if not node:
                return 0
            l, r = height(node.left), height(node.right)
            best = max(best, l + r)
            return 1 + max(l, r)
        height(root)
        return best

