class Solution:
    def isBalanced(self, root):
        def h(node):                 # height, or -1 if unbalanced somewhere below
            if not node:
                return 0
            l = h(node.left)
            if l < 0:
                return -1
            r = h(node.right)
            if r < 0 or abs(l - r) > 1:
                return -1
            return 1 + max(l, r)
        return h(root) >= 0

