    import collections

    class N:
        __slots__ = ("val", "left", "right")

        def __init__(self, v):
            self.val, self.left, self.right = v, None, None

    def build(arr):
        if not arr or arr[0] is None:
            return None
        it = iter(arr)
        root = N(next(it))
        q = collections.deque([root])
        while q:
            node = q.popleft()
            for side in ("left", "right"):
                try:
                    v = next(it)
                except StopIteration:
                    return root
                if v is not None:
                    c = N(v)
                    setattr(node, side, c)
                    q.append(c)
        return root

