        out, st, cur = [], [], build(arr)
        while st or cur:
            while cur:
                st.append(cur)
                cur = cur.left
            cur = st.pop()
            out.append(cur.val)
            cur = cur.right
        return out

    if not isinstance(got, list):
        return False
    try:
        return inorder(got) == inorder(expected)
    except Exception:
        return False

