    def insertIntoBST(self, root, val):
        new = TreeNode(val)
        if not root:
            return new
        cur = root
        while True:
            if val < cur.val:
                if not cur.left:
                    cur.left = new
                    return root
                cur = cur.left
            else:
                if not cur.right:
                    cur.right = new
                    return root
                cur = cur.right

