        def build(lo, hi):           # builds the subtree whose inorder slice is [lo, hi)
            if lo >= hi:
                return None
            val = next(it)
            node = TreeNode(val)
            mid = where[val]
            node.left = build(lo, mid)
            node.right = build(mid + 1, hi)
            return node
        return build(0, len(inorder))

