class Solution:
    def maxPathSum(self, root):
        best = root.val
        def gain(node):              # best sum of a path that starts at node and goes down
            nonlocal best
            if not node:
                return 0
            l = max(gain(node.left), 0)
            r = max(gain(node.right), 0)
            best = max(best, node.val + l + r)
            return node.val + max(l, r)
        gain(root)
        return best

